import {sample,glossary,importExample} from './data.mjs';
import {builtInExercises,pastPapers} from './collection.mjs';
import {translateText} from './translation.mjs';
import {letters,escapeHtml as h,parseQuestions,validateExercise,extractVocab,grade,createExerciseId,filterCollection,parseTranslations} from './core.mjs';
const $=s=>document.querySelector(s),key='sixthlight.reading.v1';
const paths={book:'M4 4h5a5 5 0 0 1 3 1 5 5 0 0 1 3-1h5v15h-5a5 5 0 0 0-3 1 5 5 0 0 0-3-1H4z M12 5v15',pen:'M15 4l5 5 M4 20l4-1L20 7a2 2 0 0 0-4-4L4 15z',folder:'M3 7V5h7l2 2h9v13H3z',lock:'M7 10V7a5 5 0 0 1 10 0v3 M5 10h14v11H5z M12 14v3',leaf:'M20 3C7 2 3 8 5 16c8 7 16 0 15-13z M5 20L16 8',arrow:'M5 12h14 M14 7l5 5-5 5',back:'M19 12H5 M10 7l-5 5 5 5',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',check:'M5 12l4 4L19 6',target:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',plus:'M12 5v14 M5 12h14',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h.1 M3 12h.1 M3 18h.1',cards:'M5 4h14v16H5z M2 7v16h14',bulb:'M9 21h6 M9 17v-2a6 6 0 1 1 6 0v2z',flag:'M5 21V3 M5 4c5-3 9 3 14 0v10c-5 3-9-3-14 0',search:'M20 20l-5-5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.book}"/></svg>`;
let storageOK=true,db;
try{db=JSON.parse(localStorage.getItem(key));if(!db||db.version!==1||!Array.isArray(db.exercises)||!Array.isArray(db.vocab)||!db.progress)db=null;}catch{storageOK=false;}
db??={version:1,exercises:[],vocab:[],progress:{},activeId:sample.id};
db.translations??={};
let view='library',mode='focus',questionIndex=0,reviewMode='cards',reviewFilter='pending',reviewIndex=0,flipped=false,wordDraft=null,importDraft={},toastTimer,summaryExpanded=false;
let libraryKind='mock',libraryYear='all',libraryQuery='',visibleTranslations=new Set(),translationController=null,translationBusy=false,translationTargetId=null;
function exercises(){return [...builtInExercises,...db.exercises.map(e=>({...e,kind:'custom'}))];}
function exercise(){return exercises().find(e=>e.id===db.activeId)||builtInExercises[0];}
function progress(){const id=exercise().id;return db.progress[id]??=( {paragraph:0,read:[],answers:{},elapsed:0,completed:false});}
function persist(){try{localStorage.setItem(key,JSON.stringify(db));storageOK=true;}catch{storageOK=false;$('.local-status').innerHTML='<i></i> 保存失败，请导出备份';} }
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
const fmtTime=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;
const wordCount=e=>e.paragraphs.join(' ').match(/\b[\w’-]+\b/g)?.length||0;
const findSaved=term=>db.vocab.find(v=>v.term.toLowerCase()===term.toLowerCase());
function lookup(term){const low=term.toLowerCase();return glossary.find(v=>(v.term===low||v.forms?.includes(low)))||glossary.find(v=>!v.term.includes(' ')&&['s','es','d','ed','ing'].some(s=>v.term+s===low));}
function renderSidebar(){
 $('#sidebar').innerHTML=`<div class="brand"><div class="brand-mark">${icon('book')}</div><div class="brand-text"><div class="brand-name">拾光阅读</div><div class="brand-sub">CET-6 READING LAB</div></div></div><div class="nav-caption">MY LEARNING SPACE</div><nav aria-label="主导航">${[['reading','book','阅读练习',''],['vocab','pen','我的生词本',db.vocab.length],['library','folder','练习集',exercises().length+pastPapers.length]].map(([id,ic,label,count])=>`<button class="nav-item ${view===id?'active':''}" data-action="view" data-view="${id}" title="${label}" ${view===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${count!==''?`<b class="nav-count">${count}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('leaf')}<p>不必一口气读完，<br>读懂一段就很好。</p><small>ONE PARAGRAPH AT A TIME.</small></div><div class="private-label">${icon('lock')}<span>公开站点 · 本机学习记录</span></div></div>`;
}
function heading(eyebrow,title,description){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="heading-decoration"><svg class="leaf-illustration" aria-hidden="true" viewBox="0 0 64 64"><path d="M30 58C27 40 34 28 48 13 M33 38C13 38 13 19 16 12c16 3 22 12 17 26z M36 31C33 12 46 6 56 7c1 14-5 23-20 24z M29 49C13 53 6 45 5 35c13-3 22 2 24 14z"/></svg><div class="date-note">慢慢读，<br>也在向前。</div></div></div>`;}
function render(){questionIndex=Math.max(0,Math.min(questionIndex,exercise().questions.length-1));renderSidebar();$('#pageLabel').textContent={reading:'阅读练习',vocab:'我的生词本',library:'练习集'}[view];$('#main').innerHTML=view==='reading'?readingHTML():view==='vocab'?vocabHTML():libraryHTML();if(!storageOK)$('.local-status').innerHTML='<i></i> 保存不可用';}
function readingHTML(){const e=exercise(),p=progress(),g=grade(e.questions,p.answers),q=e.questions[questionIndex],a=p.answers[questionIndex],time=Math.ceil(wordCount(e)/100);return `${heading('A LITTLE FOCUS, A LITTLE PROGRESS','读懂一段，再向前一步。','把注意力交给眼前这一段。遇到不认识的词，点一下就能记下来。')}<section class="session-strip" aria-label="当前学习进度"><div class="session-icon">${icon('leaf')}</div><div><div class="session-title">${p.completed?'已完成的阅读，值得再看一遍':'今天，从这一篇开始'}</div><div class="session-sub">${h(e.category)} · ${e.questions.length} 道理解题</div></div><div class="session-stat">${icon('clock')}<span><strong id="sessionTimer">${fmtTime(p.elapsed)}</strong> 已专注</span></div><div class="session-stat optional"><strong>${wordCount(e)}</strong> 词 · 约 ${time} 分钟</div><div class="session-progress"><div><span>作答进度</span><span>${g.submitted} / ${g.total}</span></div><div class="progress-track"><i style="width:${g.submitted/g.total*100}%"></i></div></div></section><div class="workspace"><div><section class="card article-card" aria-label="阅读文章"><div class="article-toolbar"><span class="section-label">${icon('book')} 阅读原文</span><div class="segmented" aria-label="阅读模式"><button class="${mode==='focus'?'active':''}" data-action="mode" data-mode="focus">分段专注</button><button class="${mode==='all'?'active':''}" data-action="mode" data-mode="all">全文阅读</button></div></div><div class="article-body"><div class="article-kicker">PASSAGE ${String(exercises().findIndex(x=>x.id===e.id)+1).padStart(2,'0')}<span>·</span><span class="tag">${h(e.category)}</span></div><h2>${h(e.title)}</h2><div class="article-meta"><span>${h(e.subtitle||'我的自定义阅读')}</span><span>${wordCount(e)} words</span><span>${e.paragraphs.length} paragraphs</span></div><div class="article-divider"></div><div class="paragraph-strip"><div class="paragraph-tabs" aria-label="选择阅读段落">${e.paragraphs.map((_,i)=>`<button class="para-tab ${p.paragraph===i?'active':''} ${p.read.includes(i)?'done':''}" data-action="paragraph" data-index="${i}" aria-label="第 ${i+1} 段${p.read.includes(i)?'，已读':''}" aria-pressed="${p.paragraph===i}">${String(i+1).padStart(2,'0')}</button>`).join('')}</div><span class="read-count">${p.read.length} / ${e.paragraphs.length} 段已读</span><button class="text-button" data-action="full-translation">全文中英对照 ${icon('book')}</button></div><div class="paragraphs" id="articleText">${e.paragraphs.map((text,i)=>{if(mode==='focus'&&p.paragraph!==i)return '';const evidence=a?.submitted&&q.evidence===i;return `<section class="paragraph ${evidence?'evidence':''}" data-paragraph="${i}"><div class="paragraph-number">PARAGRAPH ${String(i+1).padStart(2,'0')}${evidence?'<span class="evidence-badge">● 本题原文依据</span>':''}</div><p>${renderParagraph(text,evidence?q.quote:null)}</p>${paragraphTranslationHTML(e,i)}</section>`;}).join('')}</div><div class="article-hint">${icon('bulb')} 小提示：先找这一段的主旨，再关注细节；点击单词或划选词组即可收藏。</div></div><div class="article-navigation"><button class="button" data-action="prev-paragraph" ${p.paragraph===0?'disabled':''}>${icon('back')} 上一段</button><button class="button primary" data-action="read-next">${p.paragraph===e.paragraphs.length-1?(p.read.includes(p.paragraph)?'这一篇，读完了':'标记本段已读'):'读完这段，继续'} ${icon('arrow')}</button></div><div class="article-bottom"><span>${icon('pen')} <button class="text-button" data-action="save-selection">收藏选中文字</button></span><span class="source-extra">${h(e.source)}</span></div></section><section class="card vocab-preview"><div class="vocab-preview-header"><h3>值得留意的表达</h3><small>点击看看，把它变成熟悉的词</small></div>${extractVocab(e.paragraphs[p.paragraph],glossary).slice(0,3).map(v=>`<button class="word-chip" data-action="word" data-term="${h(v.term)}">${h(v.term)} <b>${findSaved(v.term)?'✓':'＋'}</b></button>`).join('')||'<small>发现生词时，点击或划选原文来记录。</small>'}</section></div><aside class="question-panel" id="questionPanel"><section class="card question-card"><div class="question-head"><h3>${icon('pen')} 理解与练习</h3><span>QUESTION ${String(questionIndex+1).padStart(2,'0')} / ${String(e.questions.length).padStart(2,'0')}</span></div><div class="question-dots" aria-label="题目导航">${e.questions.map((_,i)=>{const ans=p.answers[i];return `<button class="question-dot ${i===questionIndex?'active':''} ${ans?.submitted?(ans.choice===e.questions[i].answer?'correct':'incorrect'):''}" data-action="question" data-index="${i}" aria-label="第 ${i+1} 题${ans?.submitted?'，已提交':''}" aria-pressed="${i===questionIndex}">${i+1}</button>`;}).join('')}</div><div class="question-type">${h(q.skill||'阅读理解')} · SINGLE CHOICE</div><h3 class="question-prompt">${h(q.prompt)}</h3><div class="options" role="radiogroup" aria-label="第 ${questionIndex+1} 题答案">${q.options.map((o,i)=>{const l=letters[i];return `<button class="option ${a?.choice===l?'selected':''} ${a?.submitted&&q.answer===l?'is-correct':''} ${a?.submitted&&a.choice===l&&q.answer!==l?'is-wrong':''}" data-action="answer" data-choice="${l}" role="radio" aria-checked="${a?.choice===l}" ${a?.submitted?'disabled':''}><span class="option-letter">${a?.submitted&&q.answer===l?'✓':l}</span><span class="option-text">${h(o)}</span></button>`;}).join('')}</div>${a?.submitted?`<div class="answer-panel"><div class="answer-result ${a.choice===q.answer?'':'wrong'}"><strong>${a.choice===q.answer?'✓ 回答正确':'再看一次原文'}</strong><span>正确答案 ${q.answer}</span></div>${q.quote?`<blockquote>“${h(q.quote)}”</blockquote>`:''}<p>${h(q.explanation)}</p><button class="text-button" data-action="evidence">定位第 ${q.evidence+1} 段依据 ${icon('arrow')}</button></div>`:`<div class="submit-area"><button class="button primary wide" data-action="submit-answer" ${!a?.choice?'disabled':''}>确认答案 ${icon('arrow')}</button><div class="submit-note">选择后提交，即可查看原文依据与解析</div></div>`}<div class="question-navigation"><button class="text-button" data-action="prev-question" ${questionIndex===0?'disabled':''}>← 上一题</button><button class="text-button" data-action="next-question" ${questionIndex===e.questions.length-1?'disabled':''}>下一题 →</button></div></section><div class="question-footer"><button class="finish-button ${g.complete?'ready':''}" data-action="finish">${icon('flag')}${g.complete?(p.completed?'查看本篇总结':'完成本篇 · 查看复习清单'):`完成本篇 · 已答 ${g.submitted}/${g.total}`}</button></div><div class="margin-note">${icon('leaf')}<span>错一题，也能带走一个新发现。<br>把依据找出来，比急着选对更重要。</span></div></aside></div>`;}
function tokenHTML(text){return text.split(/([A-Za-z]+(?:['’\-][A-Za-z]+)*)/g).map((s,i)=>i%2?`<span class="token ${lookup(s)?'known-word':''} ${findSaved(lookup(s)?.term||s)?'saved-word':''}" data-word="${h(s)}">${h(s)}</span>`:h(s)).join('');}
function renderParagraph(text,quote){if(!quote||!text.includes(quote))return tokenHTML(text);const start=text.indexOf(quote);return tokenHTML(text.slice(0,start))+'<mark>'+tokenHTML(quote)+'</mark>'+tokenHTML(text.slice(start+quote.length));}
function sentenceFor(term,e=exercise()){const forms=[term,...(lookup(term)?.forms||[])];const matches=text=>forms.some(form=>text.toLowerCase().includes(form.toLowerCase()));const para=e.paragraphs.find(matches);if(!para)return '';return (para.match(/[^.!?]+[.!?]?/g)||[para]).find(matches)?.trim()||para;}
function openWord(term,context){const clean=term.trim().replace(/^[^a-zA-Z]+|[^a-zA-Z]+$/g,'');if(!clean||clean.length>90){toast('请选择一个英文单词或简短词组');return;}const known=lookup(clean),saved=findSaved(known?.term||clean);wordDraft={term:known?.term||clean.toLowerCase(),pos:known?.pos||saved?.pos||'',context:context||saved?.context||sentenceFor(clean),source:saved?.source||exercise().title,exerciseId:saved?.exerciseId||exercise().id};$('#wordTitle').textContent=wordDraft.term;$('#wordMeta').innerHTML=`<div class="word-pos">${h(wordDraft.pos||'自定义词汇')}</div>`;$('#wordMeaning').value=saved?.meaning||known?.meaning||'';$('#wordNote').value=saved?.note||'';$('#wordContext').textContent=wordDraft.context||'记录这个词在文章中的用法，会更容易记住。';$('#dictionaryNote').textContent=known?'内置学习词表释义 · 可按本文语境修改':'内置词表暂未收录这个词，请填入查到的释义。';$('#wordSave').textContent=saved?'保存修改':'加入生词本';$('#wordDialog').showModal();window.getSelection()?.removeAllRanges();setTimeout(()=>$('#wordMeaning').focus(),0);}
function saveWord(ev){ev.preventDefault();const meaning=$('#wordMeaning').value.trim();if(!meaning){$('#wordMeaning').setCustomValidity('请填写释义');$('#wordMeaning').reportValidity();return;}const old=findSaved(wordDraft.term),v={...wordDraft,meaning,note:$('#wordNote').value.trim(),mastered:old?.mastered||false,createdAt:old?.createdAt||Date.now()};if(old)Object.assign(old,v);else db.vocab.push(v);persist();$('#wordDialog').close();render();toast(old?'生词卡已更新':'已加入生词本，下次见面就更熟悉了');}
function selectedText(){const sel=window.getSelection();if(!sel||sel.isCollapsed||!sel.rangeCount)return null;const node=sel.getRangeAt(0).commonAncestorContainer,el=node.nodeType===1?node:node.parentElement;if(!el.closest('#articleText'))return null;const text=sel.toString().trim();return text&&text.length<=90&&/[a-z]/i.test(text)?{text,context:el.closest('.paragraph')?.querySelector('p')?.textContent||''}:null;}
function reviewWords(){return db.vocab.filter(v=>reviewFilter==='all'||(reviewFilter==='mastered'?v.mastered:!v.mastered));}
function vocabHTML(){const words=reviewWords();reviewIndex=Math.min(reviewIndex,Math.max(words.length-1,0));const v=words[reviewIndex];return `${heading('WORDS THAT STAY WITH YOU','让生词，成为你的词。',`已收藏 ${db.vocab.length} 个词与词组，其中 ${db.vocab.filter(v=>v.mastered).length} 个已掌握。短短几分钟，温习一次就好。`)}<div class="review-toolbar"><div class="review-filter">${[['pending','待复习'],['mastered','已掌握'],['all','全部词汇']].map(([id,label])=>`<button class="filter-button ${reviewFilter===id?'active':''}" data-action="review-filter" data-filter="${id}">${label} ${id==='all'?db.vocab.length:db.vocab.filter(v=>id==='mastered'?v.mastered:!v.mastered).length}</button>`).join('')}</div><div class="review-actions"><div class="segmented"><button class="${reviewMode==='cards'?'active':''}" data-action="review-mode" data-mode="cards">卡片复习</button><button class="${reviewMode==='list'?'active':''}" data-action="review-mode" data-mode="list">词汇列表</button></div><button class="button small" data-action="export">${icon('download')} 导出 CSV</button></div></div>${!words.length?`<div class="empty-state">${icon('pen')}<h2>${db.vocab.length?'这一组词，已经复习完了':'把第一次遇见的词留在这里'}</h2><p>${db.vocab.length?'试试切换到全部词汇，看看已经走过的路。':'阅读时点击单词或划选词组，写下释义，就能开始卡片复习。'}</p><button class="button primary" data-action="view" data-view="reading">去读一段 ${icon('arrow')}</button></div>`:reviewMode==='cards'?`<div class="flashcard-progress">${String(reviewIndex+1).padStart(2,'0')} / ${String(words.length).padStart(2,'0')} · 先想想意思，再翻开卡片</div><button class="card flashcard wide" data-action="flip" aria-label="${flipped?'隐藏':'显示'} ${h(v.term)} 的释义"><span class="eyebrow">${flipped?'A WORD, NOW A LITTLE CLOSER':'DO YOU REMEMBER?'}</span><h2>${h(v.term)}</h2>${flipped?`<div class="meaning">${h(v.meaning)}</div><div class="word-pos">${h(v.pos)}</div>${v.note?`<p class="field-help">我的笔记：${h(v.note)}</p>`:''}<div class="context">${h(v.context)}</div>`:'<div class="flip-hint">点击卡片，查看释义与原文语境</div>'}</button><div class="flashcard-actions"><button class="button" data-action="review-next">${icon('back')} 再想一想</button><button class="button primary" data-action="master" data-term="${h(v.term)}">${icon('check')} ${v.mastered?'移回待复习':'这个词记住了'}</button></div>`:`<div class="vocab-list">${words.map(w=>`<article class="card vocab-list-card"><div class="vocab-list-top"><div><h3>${h(w.term)}</h3><div class="pos">${h(w.pos||'自定义词汇')}</div></div>${w.mastered?'<span class="mastered-badge">已掌握</span>':''}</div><div class="meaning">${h(w.meaning)}</div>${w.note?`<p class="field-help">笔记：${h(w.note)}</p>`:''}<p class="context">${h(w.context)}</p><div class="vocab-list-bottom"><span>来自 ${h(w.source.length>23?w.source.slice(0,23)+'…':w.source)}</span><div><button class="text-button" data-action="word" data-term="${h(w.term)}">编辑</button><button class="button ghost small" data-action="master" data-term="${h(w.term)}">${w.mastered?'待复习':'掌握'}</button><button class="text-button" data-action="delete-word" data-term="${h(w.term)}" aria-label="删除 ${h(w.term)}">${icon('trash')}</button></div></div></article>`).join('')}</div>`}`;}
function libraryHTML(){
 const all=[...exercises(),...pastPapers],items=filterCollection(all,{kind:libraryKind,year:libraryYear,query:libraryQuery});
 const filters=[['mock','原创模拟',builtInExercises.length],['past-source','历年真题',pastPapers.length],['custom','自行导入',db.exercises.length],['all','全部',all.length]];
 return `${heading('CHOOSE A PASSAGE, FIND YOUR PACE','从你想读的一篇开始。','内置模拟题可以直接练习，也可以按年份查找真题，再导入自己的阅读材料。')}<section class="collection-overview"><div><strong>${builtInExercises.length}</strong><span>篇原创模拟 · 含译文解析</span></div><div><strong>${builtInExercises.reduce((n,e)=>n+e.questions.length,0)}</strong><span>道理解题 · 逐题定位依据</span></div><div><strong>${pastPapers.length}</strong><span>个历年真题原题入口</span></div></section><div class="collection-toolbar"><div class="review-filter">${filters.map(([kind,label,count])=>`<button class="filter-button ${libraryKind===kind?'active':''}" data-action="library-kind" data-kind="${kind}">${label} <span>${count}</span></button>`).join('')}</div><form id="librarySearch" class="library-search"><select id="libraryYear" aria-label="按真题年份筛选"><option value="all">全部年份</option>${[2025,2024,2023,2022,2021].map(y=>`<option value="${y}" ${libraryYear===String(y)?'selected':''}>${y} 年</option>`).join('')}</select><input id="libraryQuery" aria-label="搜索练习" placeholder="搜索标题、主题或月份" value="${h(libraryQuery)}"><button class="button small" type="submit">${icon('search')} 搜索</button></form></div>${libraryKind==='past-source'||libraryKind==='all'?'<div class="source-notice">真题卡片在来源站打开原题，尚未在本站内置全文。你可以将自己持有的文章、题目与解析导入为本机练习。来源：英语真题在线（第三方整理），核验于 2026-10-24。</div>':''}<div class="library-grid">${items.map(e=>e.kind==='past-source'?sourceCardHTML(e):exerciseCardHTML(e)).join('')}${libraryKind==='custom'||libraryKind==='all'?`<button class="import-tile" data-action="import">${icon('plus')}<strong>放入一篇新阅读</strong><small>粘贴文章、题目、答案与可选译文</small></button>`:''}</div>${!items.length?'<div class="empty-state"><h2>这里还没有匹配的练习</h2><p>换个关键词，或把你正在刷的阅读导入进来。</p><button class="button" data-action="library-clear">清除筛选</button></div>':''}`;
}
function sourceCardHTML(e){return `<article class="card exercise-card source-card"><div class="exercise-card-tags"><span class="collection-badge source">真题原题入口 ↗</span><span class="tag">${e.year} / ${String(e.month).padStart(2,'0')}</span></div><div class="eyebrow">PAST PAPER · EXTERNAL SOURCE</div><h2>${h(e.title)}</h2><p>${h(e.source)}<br>打开原题页面查看阅读材料；本站不转载该试卷全文。</p><div class="exercise-card-footer"><a class="button primary small" href="${h(e.sourceUrl)}" target="_blank" rel="noopener noreferrer">查看真题原文 ↗</a><button class="text-button" data-action="source-import" data-id="${e.id}">导入本机练习</button></div></article>`;}
function exerciseCardHTML(e){const p=db.progress[e.id],g=grade(e.questions,p?.answers||{}),builtIn=builtInExercises.some(b=>b.id===e.id);return `<article class="card exercise-card"><div class="exercise-card-tags"><span class="collection-badge">${builtIn?'内置可练 · 原创模拟':'我的导入'}</span><span class="tag">${h(e.level||'自定义')}</span></div><div class="eyebrow">${h(e.category)} · ${e.translations?.length?'含逐段译文':'支持在线参考翻译'}</div><h2>${h(e.title)}</h2><div class="exercise-subtitle">${h(e.subtitle)}</div><p>${wordCount(e)} 词 · ${e.paragraphs.length} 段 · ${e.questions.length} 题<br>${h(e.source)}</p><div class="exercise-card-footer"><span>${p?.completed?'✓ 已完成':g.submitted?`已答 ${g.submitted}/${g.total}`:'准备好就出发'}</span><button class="button small ${e.id===db.activeId?'primary':''}" data-action="open-exercise" data-id="${e.id}">${p?'继续练习':'开始阅读'} ${icon('arrow')}</button></div>${!builtIn?`<button class="text-button" data-action="delete-exercise" data-id="${e.id}" style="align-self:flex-end;margin-top:10px;font-size:9px;color:#829076">删除练习</button>`:''}</article>`;}
function currentReviewList(){const e=exercise(),auto=extractVocab(e.paragraphs.join(' '),glossary);const saved=db.vocab.filter(v=>v.exerciseId===e.id);const combined=[...saved,...auto.filter(v=>!saved.some(s=>s.term===v.term))];return combined;}
function summaryHTML(){const e=exercise(),p=progress(),g=grade(e.questions,p.answers),list=currentReviewList(),shown=summaryExpanded?list:list.slice(0,12);return `<div class="summary-top"><span class="eyebrow">ONE PASSAGE, A LITTLE PROGRESS</span><button class="icon-button" data-close="summaryDialog" aria-label="关闭总结">×</button></div><div class="summary-hero"><div class="summary-icon">${icon('leaf')}</div><h2>这一篇，你已经向前了一步。</h2><p>${h(e.title)}<br>带走几个值得再见的词，也带走找依据的方法。</p><div class="summary-stats"><div class="summary-stat"><strong>${g.correct}<small style="font-size:14px"> / ${g.total}</small></strong><span>答对题目</span></div><div class="summary-stat"><strong>${fmtTime(p.elapsed)}</strong><span>专注阅读</span></div><div class="summary-stat"><strong>${list.length}</strong><span>可复习表达</span></div></div><div class="wrong-link">${e.questions.map((q,i)=>p.answers[i]?.choice!==q.answer?`<button data-action="revisit" data-index="${i}">回看第 ${i+1} 题 →</button>`:'').join('')}</div></div><div class="summary-vocab-title"><div><h3>本篇复习清单</h3><p>匹配内置六级常见表达 + 你在阅读中记录的生词</p></div><button class="button small" data-action="save-all">${icon('plus')} 全部加入生词本</button></div><div class="summary-list">${shown.map(v=>`<div class="summary-word"><div><strong>${h(v.term)}</strong><small>${h(v.meaning)}</small></div><button class="icon-button" data-action="save-term" data-term="${h(v.term)}" aria-label="${findSaved(v.term)?'已收藏':'收藏'} ${h(v.term)}">${findSaved(v.term)?'✓':'＋'}</button></div>`).join('')||'<p class="empty-summary">本篇未匹配到内置词表，阅读时收藏的生词会显示在这里。</p>'}</div>${list.length>12?`<button class="text-button" data-action="expand-summary" style="margin-top:12px">${summaryExpanded?'收起词表':`展开其余 ${list.length-12} 个表达`} ↓</button>`:''}<div class="summary-actions"><button class="button" data-action="restart">再练一次</button><button class="button primary" data-action="go-review">去生词本复习 ${icon('arrow')}</button></div>`;}
function openSummary(){summaryExpanded=false;$('#summaryContent').innerHTML=summaryHTML();$('#summaryDialog').showModal();}
function addTerm(term){if(findSaved(term))return false;const v=currentReviewList().find(v=>v.term===term)||lookup(term);if(!v)return false;db.vocab.push({...v,context:sentenceFor(term),source:exercise().title,exerciseId:exercise().id,mastered:false,note:'',createdAt:Date.now()});return true;}
function showImport(){importDraft={title:'',article:'',raw:'',translationText:'',translations:[],questions:[],paragraphs:[]};renderImportStep1();$('#importDialog').showModal();}
function renderImportStep1(){$('#stepOne').classList.add('active');$('#stepTwo').classList.remove('active');$('#importContent').innerHTML=`<div class="import-guide">文章段落之间留一个空行。题目以 1. 或 46. 开头，选项使用 A) 或 A.。可附“答案：B / 依据：2 / 解析：…”；缺少的内容在下一步补充。</div><label class="field-label" for="importTitle">文章标题</label><input id="importTitle" maxlength="160" placeholder="给这篇阅读起个名字" value="${h(importDraft.title)}"><div class="import-grid"><div><label class="field-label" for="importArticle">阅读文章 <span>最多 30,000 字符</span></label><textarea id="importArticle" maxlength="30000" placeholder="Paste your passage here…&#10;&#10;Start a new paragraph with a blank line.">${h(importDraft.article)}</textarea></div><div><label class="field-label" for="importQuestions">题目与解析 <span>支持中英文标签</span></label><textarea id="importQuestions" maxlength="30000" placeholder="${h(importExample)}">${h(importDraft.raw)}</textarea></div></div><label class="field-label" for="importTranslations">中文译文 <span>选填，与原文逐段对应，段落之间留空行</span></label><textarea id="importTranslations" rows="3" maxlength="30000" placeholder="已有参考译文可以一起粘贴；也可导入后按需翻译。">${h(importDraft.translationText||'')}</textarea><div id="importError" class="form-error" role="alert"></div><div class="import-bottom"><p>只按你提供的答案与解析反馈，不自动猜答案。内容仅保存在当前浏览器中。</p><div class="button-row"><button class="button" data-action="fill-example">填入格式示例</button><button class="button primary" data-action="parse-import">识别并核对 ${icon('arrow')}</button></div></div>`;}
function parseImport(){importDraft.title=$('#importTitle').value.trim();importDraft.article=$('#importArticle').value.trim();importDraft.raw=$('#importQuestions').value.trim();importDraft.translationText=$('#importTranslations').value.trim();if(!importDraft.title||!importDraft.article||!importDraft.raw){$('#importError').textContent='请填写标题、文章和题目。';return;}importDraft.paragraphs=importDraft.article.split(/\n\s*\n/).map(x=>x.trim().replace(/\n/g,' ')).filter(Boolean);try{importDraft.translations=parseTranslations(importDraft.translationText,importDraft.paragraphs.length);}catch(error){$('#importError').textContent=error.message;return;}importDraft.questions=parseQuestions(importDraft.raw);if(!importDraft.questions.length||importDraft.questions.length>30||importDraft.paragraphs.length>50){$('#importError').textContent='请检查题目编号格式。首版支持最多 30 题、50 段。';return;}renderImportStep2();}
function renderImportStep2(){$('#stepOne').classList.remove('active');$('#stepTwo').classList.add('active');$('#importContent').innerHTML=`<div class="import-preview-heading"><strong>已识别 ${importDraft.paragraphs.length} 段 · ${importDraft.questions.length} 题</strong><span>核对正确答案、依据段落与解析</span></div>${importDraft.questions.map((q,i)=>`<section class="import-q" data-import-q="${i}"><label class="field-label">第 ${i+1} 题题干<input data-field="prompt" value="${h(q.prompt)}" maxlength="1000" aria-label="第 ${i+1} 题题干"></label><div class="import-q-fields">${q.options.map((o,j)=>`<label class="field-label" style="margin-top:6px">选项 ${letters[j]}<input data-option="${j}" value="${h(o)}" maxlength="1000" aria-label="第 ${i+1} 题选项 ${letters[j]}"></label>`).join('')}</div><div class="import-q-fields"><label class="field-label">正确答案<select data-field="answer"><option value="">请选择</option>${letters.map(l=>`<option value="${l}" ${q.answer===l?'selected':''}>${l}</option>`).join('')}</select></label><label class="field-label">原文依据<select data-field="evidence"><option value="-1">请选择依据段落</option>${importDraft.paragraphs.map((p,n)=>`<option value="${n}" ${q.evidence===n?'selected':''}>第 ${n+1} 段 · ${h(p.slice(0,65))}…</option>`).join('')}</select></label></div><label class="field-label">解析<textarea data-field="explanation" maxlength="3000" placeholder="解释正确选项如何对应原文，也可以写下干扰项的问题。">${h(q.explanation)}</textarea></label></section>`).join('')}<div id="importError" class="form-error" role="alert"></div><div class="import-bottom"><p>你的答案与解析会在提交每道题后显示。阅读依据定位到所选原文段落。</p><div class="button-row"><button class="button" data-action="import-back">返回编辑</button><button class="button primary" data-action="create-exercise">保存并开始练习 ${icon('arrow')}</button></div></div>`;}
function captureImportPreview(){document.querySelectorAll('[data-import-q]').forEach(el=>{const q=importDraft.questions[+el.dataset.importQ];el.querySelectorAll('[data-field]').forEach(input=>{q[input.dataset.field]=input.dataset.field==='evidence'?Number(input.value):input.value.trim();});el.querySelectorAll('[data-option]').forEach(input=>q.options[+input.dataset.option]=input.value.trim());});}
function createExercise(){captureImportPreview();const e={kind:'custom',translations:importDraft.translations||[],translationSource:'自行导入译文',id:createExerciseId(),title:importDraft.title,paragraphs:importDraft.paragraphs,questions:importDraft.questions,subtitle:'我的自定义阅读',category:'自定义练习',source:'自行导入 · 答案解析由导入内容提供'};const error=validateExercise(e);if(error){$('#importError').textContent=error;$('#importError').scrollIntoView({block:'nearest'});return;}db.exercises.push(e);db.activeId=e.id;questionIndex=0;mode='focus';view='reading';persist();$('#importDialog').close();render();window.scrollTo({top:0});toast('练习已保存，从第一段慢慢开始');}
function askConfirm(title,text,onYes){$('#confirmTitle').textContent=title;$('#confirmText').textContent=text;$('#confirmYes').onclick=()=>{$('#confirmDialog').close();onYes();};$('#confirmDialog').showModal();}
function exportWords(){if(!db.vocab.length){toast('先收藏一些生词，就能导出了');return;}const cell=s=>'"'+String(s??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const rows=[['单词或词组','词性','释义','例句','笔记','掌握状态','来源'],...db.vocab.map(v=>[v.term,v.pos,v.meaning,v.context,v.note,v.mastered?'已掌握':'待复习',v.source])];const blob=new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='拾光阅读_生词本.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('生词本已导出');}
function setQuestion(i){questionIndex=Math.max(0,Math.min(exercise().questions.length-1,i));progress().question=questionIndex;const q=exercise().questions[questionIndex];if(progress().answers[questionIndex]?.submitted)progress().paragraph=q.evidence;persist();render();}
function switchExercise(id){visibleTranslations.clear();db.activeId=id;view='reading';questionIndex=progress().question||0;mode='focus';persist();render();window.scrollTo({top:0});}
function getTranslation(e,i){const saved=db.translations[e.id]?.[i];return saved?{text:saved.text,source:saved.source}: {text:e.translations?.[i]||'',source:e.translationSource||'参考译文'};}
function paragraphTranslationHTML(e,i){const entry=getTranslation(e,i),visible=visibleTranslations.has(i);return `<div class="paragraph-translation"><button class="text-button" data-action="toggle-translation" data-index="${i}" aria-expanded="${visible}">${visible?'收起本段译文':'查看本段译文'} <span aria-hidden="true">${visible?'−':'＋'}</span></button>${visible?`<div class="translation-note"><div class="translation-note-label">${h(entry.source)} · 先读英文，再用中文核对</div>${entry.text?`<p class="translation-chinese">${h(entry.text)}</p>`:'<p class="translation-chinese muted">这段还没有译文。你可以补充译文，或按需请求在线参考翻译。</p>'}<button class="text-button" data-action="edit-translation" data-index="${i}">${entry.text?'校订译文 / 查看全文':'补充译文 / 在线翻译'} →</button></div>`:''}</div>`;}
function translationDialogHTML(e){const missing=e.paragraphs.filter((_,i)=>!getTranslation(e,i).text).length;return `<div class="dialog-heading"><div><span class="eyebrow">READ · CHECK · UNDERSTAND</span><h2>全文中英对照</h2><p class="field-help">${h(e.title)} · ${e.paragraphs.length} 段 · 译文供理解核对，可保存自己的校订</p></div><button class="icon-button" data-close="translationDialog" aria-label="关闭全文译文">×</button></div><div class="translation-service-note">已有译文可直接查看，不发送正文。点击在线翻译时，所选英文会发送给 <a href="https://mymemory.translated.net/doc/spec.php" target="_blank" rel="noopener noreferrer">MyMemory</a>；匿名服务有每日用量限制。机器译文仅供参考，可手动修订。</div><div id="translationStatus" class="translation-status" role="status" aria-live="polite"></div><div class="translation-pairs">${e.paragraphs.map((text,i)=>{const entry=getTranslation(e,i);return `<section class="translation-pair"><div class="translation-original"><div class="eyebrow">PARAGRAPH ${String(i+1).padStart(2,'0')} · ENGLISH</div><p>${h(text)}</p></div><div class="translation-result"><div class="translation-result-heading"><span id="translationSource${i}">${h(entry.text?entry.source:'等待补充译文')}</span>${!entry.text?`<button class="text-button" data-action="translate-one" data-index="${i}">发送本段并翻译 →</button>`:''}</div><label class="visually-hidden" for="translationText${i}">第 ${i+1} 段中文译文</label><textarea id="translationText${i}" data-translation-index="${i}" rows="6" maxlength="10000" placeholder="粘贴或写下本段译文…">${h(entry.text)}</textarea></div></section>`;}).join('')}</div><div class="translation-dialog-footer"><button class="button" data-action="translate-missing" ${!missing?'disabled':''}>${icon('spark')} 发送并翻译缺失段落（${missing}）</button><button class="button primary" data-action="save-translations">保存我的校订 ${icon('check')}</button></div>`;}
function openTranslationDialog(index){const e=exercise();translationTargetId=e.id;$('#translationContent').innerHTML=translationDialogHTML(e);$('#translationDialog').showModal();if(Number.isInteger(index))setTimeout(()=>$('#translationText'+index)?.focus(),0);}
function saveTranslationEdits(e){let count=0;document.querySelectorAll('[data-translation-index]').forEach(input=>{const i=+input.dataset.translationIndex,text=input.value.trim();if(text!==getTranslation(e,i).text){db.translations[e.id]??={};db.translations[e.id][i]={text,source:'我的校订译文',updatedAt:Date.now()};count++;}});persist();return count;}
async function requestTranslations(indices){
 if(translationBusy)return;
 const e=exercises().find(e=>e.id===translationTargetId);if(!e)return;
 saveTranslationEdits(e);indices=indices.filter(i=>!getTranslation(e,i).text);if(!indices.length){toast('这些段落已经有译文，可以直接检查或校订');return;}
 translationBusy=true;const controller=new AbortController();translationController=controller;const timeout=setTimeout(()=>controller.abort(),90000);
 const buttons=$('#translationDialog').querySelectorAll('[data-action="translate-one"],[data-action="translate-missing"],[data-action="save-translations"]');buttons.forEach(b=>b.disabled=true);
 const pendingFields=indices.map(i=>$('#translationText'+i)).filter(Boolean);pendingFields.forEach(field=>{field.readOnly=true;field.setAttribute('aria-busy','true');});
 let completed=0;
 try{
  for(const i of indices){$('#translationStatus').textContent=`正在翻译第 ${i+1} 段…（${completed}/${indices.length}）`;
   const text=await translateText(e.paragraphs[i],{signal:controller.signal});
   if(controller.signal.aborted)break;
   const decoder=document.createElement('textarea');decoder.innerHTML=text;
   db.translations[e.id]??={};db.translations[e.id][i]={text:decoder.value,source:'MyMemory 机器参考译文',updatedAt:Date.now()};persist();completed++;
   const field=$('#translationText'+i);if(field)field.value=decoder.value;
   const label=$('#translationSource'+i);if(label)label.textContent='MyMemory 机器参考译文';
  }
  if($('#translationDialog').open)$('#translationStatus').textContent=`已保存 ${completed} 段参考译文。请结合英文检查表达与语境。`;
 }catch(error){if($('#translationDialog').open)$('#translationStatus').textContent=error.name==='AbortError'?'翻译已停止或请求超时，已完成的段落会保留。':(error.message||'翻译暂时不可用，请手动补充译文。');}
 finally{clearTimeout(timeout);translationBusy=false;translationController=null;buttons.forEach(b=>b.disabled=false);pendingFields.forEach(field=>{field.readOnly=false;field.removeAttribute('aria-busy');});render();}
}
document.addEventListener('click',ev=>{
 const close=ev.target.closest('[data-close]');if(close){$('#'+close.dataset.close).close();return;}
 const word=ev.target.closest('[data-word]');if(word&&!window.getSelection()?.toString().trim()){openWord(word.dataset.word,word.closest('.paragraph').querySelector('p').textContent);return;}
 const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,p=progress(),e=exercise();
 if(action==='view'){view=b.dataset.view;render();window.scrollTo({top:0});}
 else if(action==='library-kind'){libraryKind=b.dataset.kind;libraryYear='all';render();}
 else if(action==='library-clear'){libraryKind='all';libraryYear='all';libraryQuery='';render();}
 else if(action==='source-import'){const source=pastPapers.find(p=>p.id===b.dataset.id);if(source){showImport();importDraft.title=source.title+' · 阅读';renderImportStep1();}}
 else if(action==='toggle-translation'){const i=+b.dataset.index;if(visibleTranslations.has(i))visibleTranslations.delete(i);else visibleTranslations.add(i);render();}
 else if(action==='full-translation')openTranslationDialog();
 else if(action==='edit-translation')openTranslationDialog(+b.dataset.index);
 else if(action==='save-translations'){const target=exercises().find(x=>x.id===translationTargetId);if(target){const count=saveTranslationEdits(target);$('#translationStatus').textContent=count?`已保存 ${count} 段校订译文，仅保存在当前浏览器。`:'译文没有修改，已有译文已保留。';render();}}
 else if(action==='translate-one')void requestTranslations([+b.dataset.index]);
 else if(action==='translate-missing'){const target=exercises().find(x=>x.id===translationTargetId);if(target)void requestTranslations(target.paragraphs.map((_,i)=>i));}
 else if(action==='mode'){mode=b.dataset.mode;render();}
 else if(action==='paragraph'){p.paragraph=+b.dataset.index;persist();render();}
 else if(action==='prev-paragraph'){p.paragraph=Math.max(0,p.paragraph-1);persist();render();}
 else if(action==='read-next'){if(!p.read.includes(p.paragraph))p.read.push(p.paragraph);if(p.paragraph<e.paragraphs.length-1)p.paragraph++;else toast('原文读完了，试着用题目检验理解吧');persist();render();}
 else if(action==='word')openWord(b.dataset.term);
 else if(action==='save-selection'){const selected=selectedText();if(selected)openWord(selected.text,selected.context);else toast('先在原文中划选一个词组，或直接点击单词');}
 else if(action==='answer'){p.answers[questionIndex]={choice:b.dataset.choice,submitted:false};persist();render();}
 else if(action==='submit-answer'){if(!p.answers[questionIndex]?.choice)return;p.answers[questionIndex].submitted=true;p.paragraph=e.questions[questionIndex].evidence;persist();render();}
 else if(action==='question')setQuestion(+b.dataset.index);
 else if(action==='prev-question')setQuestion(questionIndex-1);
 else if(action==='next-question')setQuestion(questionIndex+1);
 else if(action==='evidence'){p.paragraph=e.questions[questionIndex].evidence;persist();render();$('.article-card').scrollIntoView({behavior:'smooth',block:'start'});}
 else if(action==='finish'){const g=grade(e.questions,p.answers);if(!g.complete){const first=e.questions.findIndex((_,i)=>!p.answers[i]?.submitted);setQuestion(first);$('#questionPanel').scrollIntoView({behavior:'smooth',block:'start'});toast('还有题目未提交，先完成第 '+(first+1)+' 题');return;}p.completed=true;persist();openSummary();}
 else if(action==='revisit'){$('#summaryDialog').close();setQuestion(+b.dataset.index);$('#questionPanel').scrollIntoView({behavior:'smooth',block:'start'});}
 else if(action==='save-term'){if(addTerm(b.dataset.term)){persist();$('#summaryContent').innerHTML=summaryHTML();renderSidebar();toast('已加入生词本');}else toast('这个表达已经在生词本里了');}
 else if(action==='save-all'){let added=0;currentReviewList().forEach(v=>{if(addTerm(v.term))added++;});persist();$('#summaryContent').innerHTML=summaryHTML();renderSidebar();toast(added?`已收藏 ${added} 个表达`:'这些表达都已收藏');}
 else if(action==='expand-summary'){summaryExpanded=!summaryExpanded;$('#summaryContent').innerHTML=summaryHTML();}
 else if(action==='go-review'){$('#summaryDialog').close();view='vocab';reviewFilter='pending';reviewIndex=0;flipped=false;render();window.scrollTo({top:0});}
 else if(action==='restart'){askConfirm('重新练习这篇阅读？','本篇作答记录和计时将重新开始；已经收藏的生词会继续保留。',()=>{delete db.progress[e.id];questionIndex=0;persist();$('#summaryDialog').close();render();toast('重新开始，也许这次会有新的发现');});}
 else if(action==='review-filter'){reviewFilter=b.dataset.filter;reviewIndex=0;flipped=false;render();}
 else if(action==='review-mode'){reviewMode=b.dataset.mode;flipped=false;render();}
 else if(action==='flip'){flipped=!flipped;render();}
 else if(action==='review-next'){const words=reviewWords();reviewIndex=(reviewIndex+1)%words.length;flipped=false;render();}
 else if(action==='master'){const v=findSaved(b.dataset.term);if(v){v.mastered=!v.mastered;persist();flipped=false;render();toast(v.mastered?'又记住一个词，很好':'已移回待复习');}}
 else if(action==='delete-word'){askConfirm('删除这个生词？',`“${b.dataset.term}”及其笔记会从生词本中移除。`,()=>{db.vocab=db.vocab.filter(v=>v.term!==b.dataset.term);persist();render();toast('生词已删除');});}
 else if(action==='export')exportWords();
 else if(action==='import')showImport();
 else if(action==='fill-example'){importDraft={title:'Digital access and participation',article:sample.paragraphs[0],raw:importExample};renderImportStep1();}
 else if(action==='parse-import')parseImport();
 else if(action==='import-back'){captureImportPreview();importDraft.raw=importDraft.questions.map((q,i)=>`${i+1}. ${q.prompt}\n${q.options.map((o,j)=>letters[j]+') '+o).join('\n')}\n答案：${q.answer}\n依据：${q.evidence>=0?q.evidence+1:''}\n解析：${q.explanation}`).join('\n\n');renderImportStep1();}
 else if(action==='create-exercise')createExercise();
 else if(action==='open-exercise')switchExercise(b.dataset.id);
 else if(action==='delete-exercise'){askConfirm('删除这篇练习？','本篇文章与作答进度会被移除；收藏过的生词会保留。',()=>{db.exercises=db.exercises.filter(x=>x.id!==b.dataset.id);delete db.progress[b.dataset.id];delete db.translations[b.dataset.id];if(db.activeId===b.dataset.id){db.activeId=sample.id;questionIndex=progress().question||0;}persist();render();toast('练习已删除');});}
});
document.addEventListener('mouseup',ev=>{if(ev.target.closest('#articleText')){const s=selectedText();if(s)setTimeout(()=>{if(!$('#wordDialog').open)openWord(s.text,s.context);},30);}});
$('#wordForm').addEventListener('submit',saveWord);$('#wordMeaning').addEventListener('input',()=>$('#wordMeaning').setCustomValidity(''));
document.addEventListener('submit',ev=>{if(ev.target.id==='librarySearch'){ev.preventDefault();libraryQuery=$('#libraryQuery').value.trim();libraryYear=$('#libraryYear').value;if(libraryYear!=='all')libraryKind='past-source';render();}});
document.addEventListener('change',ev=>{if(ev.target.id==='libraryYear'){libraryYear=ev.target.value;libraryQuery=$('#libraryQuery').value.trim();if(libraryYear!=='all')libraryKind='past-source';render();}});
$('#translationDialog').addEventListener('close',()=>{translationController?.abort();render();});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',ev=>{if(ev.target===d){const r=d.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)d.close();}}));
setInterval(()=>{if(view==='reading'&&!document.hidden&&!document.querySelector('dialog[open]')){progress().elapsed++;const el=$('#sessionTimer');if(el)el.textContent=fmtTime(progress().elapsed);if(progress().elapsed%15===0)persist();}},1000);
window.addEventListener('pagehide',persist);questionIndex=Math.min(progress().question||0,exercise().questions.length-1);render();persist();
